package layout_test

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// undocumentedFunctions checks declarations independently of build constraints;
// generated files retain their generator's documentation policy.
func undocumentedFunctions(filename string, source any) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, source, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	if ast.IsGenerated(f) {
		return nil, nil
	}
	var missing []string
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if ok && strings.TrimSpace(fn.Doc.Text()) == "" {
			missing = append(missing, fmt.Sprintf("%s: %s has no function comment", fset.Position(fn.Pos()), fn.Name.Name))
		}
	}
	return missing, nil
}

// TestDocumentationFunctionComments requires meaningful prose to be attached to
// every named authored function, including platform-specific files and tests.
// Presence is mechanical; reviewers remain responsible for semantic accuracy.
func TestDocumentationFunctionComments(t *testing.T) {
	root := repoRoot(t)
	cmd := exec.CommandContext(t.Context(), "git", "ls-files", "--cached", "--others", "--exclude-standard", "-z")
	cmd.Dir = root
	files, err := cmd.Output()
	if err != nil {
		t.Fatalf("list repository files: %v", err)
	}
	checked := 0
	for _, name := range strings.Split(string(files), "\x00") {
		if !strings.HasSuffix(name, ".go") || strings.HasPrefix(name, "third_party/") || strings.HasPrefix(name, "vendor/") || strings.Contains(name, "/vendor/") {
			continue
		}
		path := filepath.Join(root, filepath.FromSlash(name))
		if _, err := os.Stat(path); os.IsNotExist(err) {
			continue // Deleted tracked files remain in the index until staged.
		}
		missing, err := undocumentedFunctions(path, nil)
		if err != nil {
			t.Errorf("%s: %v", name, err)
			continue
		}
		checked++
		for _, message := range missing {
			t.Error(message)
		}
	}
	if checked == 0 {
		t.Fatal("no Go files checked")
	}
	t.Logf("checked function comments in %d Go files across both modules and all build tags", checked)
}

// TestDocumentationCommentDetection rejects missing and misplaced comments,
// ignores literals, and honors only Go's strict generated-source marker.
func TestDocumentationCommentDetection(t *testing.T) {
	for _, tt := range []struct {
		name, source string
		missing      int
	}{
		{"missing", "package p\nfunc f() {}", 1},
		{"documented", "package p\n// f checks an enrollment.\nfunc f() {}", 0},
		{"misattached", "package p\n// f checks an enrollment.\nvar x int\nfunc f() {}", 1},
		{"directive-only", "package p\n//go:noinline\nfunc f() {}", 1},
		{"generated", "// Code generated by fixture. DO NOT EDIT.\npackage p\nfunc f() {}", 0},
		{"loose-generated", "// Generated helpers.\npackage p\nfunc f() {}", 1},
		{"other-platform", "//go:build windows\n\npackage p\nfunc f() {}", 1},
		{"literal", "package p\nvar f = func() {}", 0},
		{"method", "package p\ntype helper struct{}\nfunc (helper) f() {}", 1},
		{"test", "package p\nfunc TestContract() {}", 1},
	} {
		t.Run(tt.name, func(t *testing.T) {
			missing, err := undocumentedFunctions("fixture.go", tt.source)
			if err != nil || len(missing) != tt.missing {
				t.Fatalf("missing = %v, error = %v; want %d findings", missing, err, tt.missing)
			}
		})
	}
	if _, err := undocumentedFunctions("invalid.go", "package"); err == nil {
		t.Fatal("invalid Go source was silently accepted")
	}
}
